#include <Arduino.h>
static String input;
void setup() {
    input.reserve(8192);
    Serial.setRxBufferSize(16384);
    Serial.begin(115200);
}
void loop() {
    static unsigned long previous = 0;
    if (millis() - previous >= 1000) {
        previous = millis();
        Serial.printf("NODU_GUI_READY FLASH:%u PSRAM:%u\r\n", ESP.getFlashChipSize(), ESP.getPsramSize());
    }
    while (Serial.available()) {
        char c = Serial.read();
        if (c == '\n') { Serial.printf("NODU_GUI_ECHO:%s\r\n", input.c_str()); input = ""; }
        else if (c != '\r' && input.length() < 8192) input += c;
    }
}
